def d(n):
    if n == 1: return 0
    result = 1 + int(isqrt(n)) * (n == isqrt(n) ** 2)
    for i in range(2, isqrt(n) + 1):
        if n % i == 0:
            result += i + n // i
    return result

def amicable_numbers_sum(n):
    seen = set()
    sum_amicable = 0
    for i in range(2, n + 1):
        if i not in seen:
            d_i = d(i)
            if d(d_i) == i and i!= d_i:
                sum_amicable += i + d_i
                seen.add(d_i)
            seen.add(i)
    return sum_amicable
