from collections import defaultdict

def find_length(binary_string):
    count_map = defaultdict(int)
    count_map[0] = 1
    max_diff = 0
    curr_count = 0
    for char in binary_string:
        if char == '0':
            curr_count -= 1
        else:
            curr_count += 1
        if curr_count in count_map:
            max_diff = max(max_diff, abs(curr_count - count_map[curr_count]))
        else:
            count_map[curr_count] = curr_count
    min_count = 0
    max_count = 0
    for char in binary_string:
        if char == '0':
            curr_count = curr_count - 1
        else:
            curr_count = curr_count + 1
        min_count = min(min_count, curr_count)
        max_count = max(max_count, curr_count)
    return max(max_diff, max_count - min_count)
```

