    Check whether two arrays follow the same pattern.

    Two arrays follow the same pattern if there's a consistent one-to-one mapping
    between elements of arr1 and arr2.

    Args:
        arr1: First array
        arr2: Second array

    Returns:
        True if both arrays follow the same pattern, False otherwise
    """
    if len(arr1) != len(arr2):
        return False

    # Create mappings from arr1 to arr2 and arr2 to arr1
    mapping_1_to_2 = {}
    mapping_2_to_1 = {}

    for elem1, elem2 in zip(arr1, arr2):
        # Check if elem1 already has a mapping
        if elem1 in mapping_1_to_2:
            if mapping_1_to_2[elem1] != elem2:
