def sum_div(n):
    """Return the sum of all divisors of n, excluding n itself."""
    if n <= 1:
        return 0

    divisor_sum = 1  # 1 is always a divisor

    # Check divisors up to sqrt(n)
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            divisor_sum += i
            # Add the complementary divisor if it's different
            if i != n // i:
                divisor_sum += n // i

    return divisor_sum
